package com.typheye.wgpro.ui.function.device;
import android.os.Bundle; import androidx.appcompat.app.AppCompatActivity; import androidx.appcompat.widget.Toolbar; import androidx.fragment.app.Fragment; import com.typheye.wgpro.R; import com.typheye.wgpro.utils.AppUtils;
public class DeviceDetailActivity extends AppCompatActivity { public static final String EXTRA_ID="device_id",EXTRA_TYPE="device_type"; @Override public void onCreate(Bundle state){super.onCreate(state);AppUtils.useScreenCutArea(getWindow(),this);setContentView(R.layout.activity_device_detail);AppUtils.applyMainWindowInsets(findViewById(R.id.app_bar_layout),findViewById(R.id.device_detail_container));Toolbar toolbar=findViewById(R.id.device_detail_toolbar);setSupportActionBar(toolbar);toolbar.setNavigationOnClickListener(v->finish());if(state==null){Fragment fragment="xiaomi".equals(getIntent().getStringExtra(EXTRA_TYPE))?new XiaomiDeviceFragment():new GenericDeviceFragment();getSupportFragmentManager().beginTransaction().replace(R.id.device_detail_container,fragment).commit();}}}
